[
  {
    "statement": "Based on available studies, cutting appears to be the most evaluated method for controlling bracken in shrublands.",
    "citations": []
  },
  {
    "statement": "One systematic review found that cutting may be equally effective as the herbicide asulam for reducing bracken abundance.",
    "citations": [
      "105"
    ]
  },
  {
    "statement": "Cutting bracken was found to reduce bracken cover or biomass in multiple studies.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "A randomized, controlled, before-and-after trial in Norway showed that cutting bracken was effective.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Two randomized, controlled studies in the UK showed that cutting bracken was effective.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "The results for cutting bracken were mixed, with one study showing cutting had mixed effects on bracken cover.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "One study found no decrease in bracken abundance after cutting.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Herbicide application for bracken control was also evaluated.",
    "citations": [
      "1652"
    ]
  },
  {
    "statement": "Three randomized, controlled studies in the UK found that herbicide application reduced bracken biomass or cover.",
    "citations": [
      "1652"
    ]
  },
  {
    "statement": "One study found no change in bracken abundance following herbicide application.",
    "citations": [
      "1652"
    ]
  },
  {
    "statement": "The use of a 'bracken bruiser' was found to increase bracken cover in one study.",
    "citations": [
      "1726"
    ]
  },
  {
    "statement": "No studies were found evaluating the use of herbicide combined with sowing shrubland plant seeds in shrublands.",
    "citations": [
      "1658"
    ]
  },
  {
    "statement": "No studies were found evaluating cutting and burning methods for bracken control specifically in shrublands.",
    "citations": [
      "1655"
    ]
  }
]

[
  {
    "statement": "No studies have been found that evaluated the effects of legally protecting plant species affected by gathering on shrublands.",
    "citations": [
      "1612"
    ]
  },
  {
    "statement": "No studies have been found that evaluated the effects of placing signs to deter gathering of shrubland species.",
    "citations": [
      "1613"
    ]
  },
  {
    "statement": "No studies have been found that evaluated the effects of legally protecting habitat around shrubland on shrublands.",
    "citations": [
      "1675"
    ]
  },
  {
    "statement": "Systematic journal and report searches have been unable to assess whether legal protection actions are effective or have any harmful impacts.",
    "citations": []
  },
  {
    "statement": "The inability to assess legal protection actions is due to the absence of direct evaluation studies.",
    "citations": []
  }
]

